[asy]
import three;
import solids;

size(180);
currentprojection = perspective(3,3,2);

triple A = (1/5, 2/(15*sqrt(3)), 2*sqrt(161)/(15*sqrt(3))), B = (1,0,0), C = (1/2,sqrt(3)/2,0), O = (0,0,0), P = (A.x,A.y,0);

draw(O--A,Arrow3(6));
draw(O--B,Arrow3(6));
draw(O--C,Arrow3(6));
draw(O--P,Arrow3(6));
draw(A--P,dashed);

label("$\mathbf{a}$", A, N);
label("$\mathbf{b}$", B, SW);
label("$\mathbf{c}$", C, SE);
label("$\mathbf{p}$", P, S);
[/asy]

